using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using NCF;
public static class LocateEscapeRegression {
 static List<string> log=new List<string>();
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);log.Add("PASS "+text);}
 static void Pump(int ms){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};timer.Tick+=delegate{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
 static void Wait(Task task){var watch=System.Diagnostics.Stopwatch.StartNew();while(!task.IsCompleted&&watch.ElapsedMilliseconds<8000)Pump(10);if(!task.IsCompleted)throw new Exception("Component task timed out");task.GetAwaiter().GetResult();}
 static object Field(object o,string name){return o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static Task Call(object o,string name,params object[] args){return (Task)o.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,args);}
 static void Fixture(string path){var image=BitmapSource.Create(48,36,96,96,PixelFormats.Bgr24,null,Enumerable.Repeat((byte)150,48*36*3).ToArray(),48*3);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using(var output=new FileStream(path,FileMode.CreateNew))png.Save(output);}
 static void ManualScroll(FolderSidebar side,double offset){side.RaiseEvent(new MouseWheelEventArgs(Mouse.PrimaryDevice,Environment.TickCount,-120){RoutedEvent=Mouse.PreviewMouseWheelEvent});side.Scroll.ScrollToVerticalOffset(offset);Pump(35);}
 static void Escape(MainWindow w){var key=new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(w),Environment.TickCount,Key.Escape){RoutedEvent=Keyboard.PreviewKeyDownEvent};w.GetType().GetMethod("HandleNavigation",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(w,new object[]{key});Pump(100);}
 [STAThread]public static int Main(string[] args){string root=args[0];bool baseline=args.Length>1&&args[1]=="baseline";Directory.CreateDirectory(root);TemporarySession.RegressionRoot=Path.Combine(root,"sessions");var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());MainWindow first=null,second=null;try{
  string folder=Path.Combine(root,"Synthetic folder");Directory.CreateDirectory(folder);for(int i=0;i<30;i++)Fixture(Path.Combine(folder,i.ToString("000")+".png"));first=new MainWindow(null);first.ErrorOverride=e=>{throw new Exception(e);};first.Show();Pump(40);Wait(Call(first,"OpenPath",Path.Combine(folder,"012.png")));var side=(FolderSidebar)Field(first,"sidebar");side.Surface.Request=null;Pump(200);side.Locate();first.UpdateLayout();side.Scroll.UpdateLayout();Pump(100);double located=side.Scroll.VerticalOffset;int selectedIndex=side.Surface.Items.IndexOf(side.Session.Current);var selectedFrame=side.Surface.Frames[selectedIndex];double requested=selectedFrame.Top+selectedFrame.Height/2;ManualScroll(side,requested);side.Scroll.UpdateLayout();Pump(80);double before=side.Scroll.VerticalOffset;side.Relayout(true);Pump(80);bool scrollRetained=Math.Abs(side.Scroll.VerticalOffset-requested)<1;log.Add("TRACE located="+located+" requested="+requested+" before="+before+" after="+side.Scroll.VerticalOffset+" viewport="+side.Scroll.ViewportHeight+" extent="+side.Scroll.ExtentHeight+" selectedTop="+selectedFrame.Top);
  if(baseline){log.Add("BASELINE unchanged-layout callback returns scroll to selection: "+(!scrollRetained?"REPRODUCED":"NOT REPRODUCED"));File.WriteAllLines(Path.Combine(root,"locate-baseline.txt"),log);foreach(string line in log)Console.WriteLine(line);first.ForceTestClose();app.Shutdown();return scrollRetained?1:0;}
  Check(scrollRetained,"Locate then manual scroll is not undone by unchanged layout callback");ManualScroll(side,located+100);double manual=side.Scroll.VerticalOffset;for(int i=0;i<5;i++){side.Relayout(true);Pump(20);}Check(Math.Abs(side.Scroll.VerticalOffset-manual)<1,"Repeated thumbnail/layout callbacks do not pin manual scroll");side.Locate();Pump(50);int index=side.Surface.Items.IndexOf(side.Session.Current);var frame=side.Surface.Frames[index];Check(frame.Bottom>side.Scroll.VerticalOffset&&frame.Top<side.Scroll.VerticalOffset+side.Scroll.ViewportHeight,"Explicit repeat Locate still reveals current thumbnail");ManualScroll(side,side.Scroll.VerticalOffset+100);int anchorIndex=side.Surface.Frames.FindIndex(rect=>rect.Bottom>=side.Scroll.VerticalOffset&&rect.Top<=side.Scroll.VerticalOffset+side.Scroll.ViewportHeight);var scrollAnchor=side.Surface.Items[anchorIndex];double relative=side.Scroll.VerticalOffset-side.Surface.Frames[anchorIndex].Top;double selectedRelative=side.Scroll.VerticalOffset-side.Surface.Frames[index].Top;side.Width=380;side.UpdateLayout();side.Relayout(true);Pump(80);int newAnchorIndex=side.Surface.Items.IndexOf(scrollAnchor);double expected=side.Surface.Frames[newAnchorIndex].Top+relative;log.Add("TRACE resize firstVisible="+anchorIndex+" oldRelative="+relative+" selectedRelative="+selectedRelative+" newSelectedRelative="+(side.Scroll.VerticalOffset-side.Surface.Frames[index].Top)+" expected="+expected+" actual="+side.Scroll.VerticalOffset);Check(Math.Abs(side.Scroll.VerticalOffset-expected)<1,"Manual scroll preserves first-visible-card anchor through geometry resize");double resizedOffset=side.Scroll.VerticalOffset;side.Relayout(true);Pump(40);Check(Math.Abs(side.Scroll.VerticalOffset-resizedOffset)<1,"Post-resize thumbnail callback does not reveal selected card");Check(side.Selected.Count==1&&side.Selected.Contains(side.Session.Current),"Locate/free scroll retain current selection");
  string a=Path.Combine(root,"first-original.png"),r=Path.Combine(root,"first-result.png"),b=Path.Combine(root,"second-original.png"),q=Path.Combine(root,"second-result.png");File.WriteAllBytes(a,new byte[]{1});File.WriteAllBytes(r,new byte[]{2});File.WriteAllBytes(b,new byte[]{3});File.WriteAllBytes(q,new byte[]{4});first.ForceTestClose();first=null;
  first=new MainWindow(null);second=new MainWindow(null);first.DecisionOverride=(t,m,labels)=>2;second.DecisionOverride=(t,m,labels)=>1;first.Show();second.Show();Pump(40);first.SetTestState(a,r,false);second.SetTestState(b,q,true);
  Escape(first);Check(first.IsVisible&&first.TestDirty,"Esc Close Cancel retains addressed window and result");Check(second.IsVisible&&second.TestBusy&&!second.TestCancelRequested&&File.Exists(q),"Esc does not cancel another window or its simulated pending job");first.DecisionOverride=(t,m,labels)=>1;Escape(first);Check(!first.IsVisible&&second.IsVisible&&second.TestBusy&&!second.TestCancelRequested,"Esc Discard closes only addressed window");Check(File.ReadAllBytes(a)[0]==1&&File.ReadAllBytes(b)[0]==3&&File.Exists(q),"Originals and other window result remain unchanged");first=null;second.ForceTestClose();second=null;
  log.Add("NOTE controlled WPF routed-wheel/scroll/keyboard component checks, not native desktop input; second job is simulated, no inference. Desired Esc=current window is the new common user requirement, distinct from old Mac quit-all source.");File.WriteAllLines(Path.Combine(root,"locate-escape-report.txt"),log);foreach(string line in log)Console.WriteLine(line);app.Shutdown();return 0;
 }catch(Exception e){log.Add("FAIL "+e);File.WriteAllLines(Path.Combine(root,"locate-escape-report.txt"),log);Console.WriteLine(e);if(first!=null)first.ForceTestClose();if(second!=null)second.ForceTestClose();app.Shutdown();return 1;}}
}
